import React, { useRef } from 'react';
import { motion, useScroll, useTransform, useReducedMotion } from 'framer-motion';
import './NewLanding.css';

const FOOTER_SCROLL_OFFSET = Object.freeze(['start end', 'end end']);

const handleSocialMouseMove = (e) => {
  const rect = e.currentTarget.getBoundingClientRect();
  const x = (e.clientX - rect.left) / rect.width - 0.5;
  const y = (e.clientY - rect.top) / rect.height - 0.5;
  e.currentTarget.style.transform = `translate3d(${x * 20}px, ${y * 20}px, 0)`;
};

const handleSocialMouseLeave = (e) => {
  e.currentTarget.style.transform = 'translate3d(0, 0, 0)';
};

const NewLandingFooterComponent = () => {
  const footerRef = useRef(null);
  const prefersReducedMotion = useReducedMotion();
  const [isMobileOrTablet, setIsMobileOrTablet] = React.useState(
    typeof window !== 'undefined' ? window.matchMedia('(max-width: 1024px)').matches : false
  );

  React.useEffect(() => {
    const mediaQuery = window.matchMedia('(max-width: 1024px)');
    const handleMediaChange = (e) => setIsMobileOrTablet(e.matches);
    setIsMobileOrTablet(mediaQuery.matches);
    if (mediaQuery.addEventListener) {
      mediaQuery.addEventListener('change', handleMediaChange);
      return () => mediaQuery.removeEventListener('change', handleMediaChange);
    } else {
      mediaQuery.addListener(handleMediaChange);
      return () => mediaQuery.removeListener(handleMediaChange);
    }
  }, []);

  const disableParallax = prefersReducedMotion || isMobileOrTablet;
  
  const { scrollYProgress } = useScroll({
    target: footerRef,
    offset: FOOTER_SCROLL_OFFSET,
  });

  // Parallax: Hills move down as you scroll up away from the footer.
  // When at the bottom (progress = 1), hills are at y: 0 (static/normal).
  const hillsY = useTransform(scrollYProgress, [0, 1], [disableParallax ? 0 : 200, 0]);

  return (
    <footer id="contact" className="nl-premium-footer" ref={footerRef}>
      {/* Sky background covering the entire footer length (z-index: 0) */}
      <picture className="nl-footer-sky-bg-picture">
        <source srcSet={`${process.env.PUBLIC_URL}/bg hero.avif`} type="image/avif" />
        <source srcSet={`${process.env.PUBLIC_URL}/bg hero.webp`} type="image/webp" />
        <img
          className="nl-footer-sky-bg"
          src={`${process.env.PUBLIC_URL}/bg hero.png`}
          alt=""
          aria-hidden="true"
          loading="lazy"
          decoding="async"
        />
      </picture>
      <div className="nl-footer-sky-overlay" aria-hidden="true" />

      {/* 1. Subheading pushed above footer heading as an intro */}
      <motion.p
        className="nl-footer-motto"
        style={{ marginBottom: 40, zIndex: 5, position: 'relative' }}
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, margin: "-50px" }}
        transition={{ duration: 1.2, ease: [0.22, 1, 0.36, 1] }}
      >
        Your AI-powered conversational travel companion.<br />
        Perfectly routed adventures in seconds.
      </motion.p>

      {/* 2. Unified 3D Landscape Container for DISHASTRA and overlapping foreground hills */}
      <div className="nl-footer-landscape-container">
        {/* Layer 1: Massive DISHASTRA Text layer (One-time entrance animation) */}
        <motion.div 
          className="nl-footer-massive-wrap"
          initial={{ y: isMobileOrTablet ? 80 : (prefersReducedMotion ? 0 : 350) }}
          whileInView={{ y: 0 }}
          viewport={{ once: true, margin: "100px" }}
          transition={{ duration: 1.4, delay: 0.1, ease: [0.22, 1, 0.36, 1] }}
        >
          <h2 className="nl-massive-text">DISHASTRA</h2>
        </motion.div>

        {/* Layer 2: Foreground Hills Texture (Parallax linked to scroll) */}
        <motion.div 
          className="nl-footer-hills-bg" 
          aria-hidden="true"
          style={{ y: hillsY }}
        >
          <picture className="nl-footer-hills-img-picture">
            <source srcSet={`${process.env.PUBLIC_URL}/footer image.avif`} type="image/avif" />
            <source srcSet={`${process.env.PUBLIC_URL}/footer image.webp`} type="image/webp" />
            <img
              src={`${process.env.PUBLIC_URL}/footer image.png`}
              alt=""
              className="nl-footer-hills-img"
              loading="lazy"
              decoding="async"
            />
          </picture>
        </motion.div>

        {/* Layer 3: Gradient Vignette Fade to Black over bottom edge */}
        <div className="nl-footer-gradient-mask" aria-hidden="true" />
      </div>

      <div className="nl-footer-bottom">
        <motion.div
          className="nl-bottom-content"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 1.2, delay: 0.15, ease: [0.22, 1, 0.36, 1] }}
        >
          <div className="nl-copyright">
            © 2026 Dishastra AI. All rights reserved.
          </div>
          <div className="nl-social-links">
            <a
              href="https://twitter.com"
              target="_blank"
              rel="noreferrer"
              className="nl-social-link"
              aria-label="X (Twitter)"
              onMouseMove={handleSocialMouseMove}
              onMouseLeave={handleSocialMouseLeave}
            >
              <svg viewBox="0 0 24 24"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
            </a>
            <a
              href="https://instagram.com"
              target="_blank"
              rel="noreferrer"
              className="nl-social-link"
              aria-label="Instagram"
              onMouseMove={handleSocialMouseMove}
              onMouseLeave={handleSocialMouseLeave}
            >
              <svg viewBox="0 0 24 24"><path d="M12 2.163c3.204 0 3.584.012 4.85.07 3.252.148 4.771 1.691 4.919 4.919.058 1.265.069 1.645.069 4.849 0 3.205-.012 3.584-.069 4.849-.149 3.225-1.664 4.771-4.919 4.919-1.266.058-1.644.07-4.85.07-3.204 0-3.584-.012-4.849-.07-3.26-.149-4.771-1.699-4.919-4.92-.058-1.265-.07-1.644-.07-4.849 0-3.204.012-3.584.07-4.849.149-3.227 1.664-4.771 4.919-4.919 1.266-.057 1.645-.069 4.849-.069zm0-2.163c-3.259 0-3.667.014-4.947.072-4.358.2-6.78 2.618-6.98 6.98-.059 1.281-.073 1.689-.073 4.948 0 3.259.014 3.668.072 4.948.2 4.358 2.618 6.78 6.98 6.98 1.281.058 1.689.072 4.948.072 3.259 0 3.668-.014 4.948-.072 4.354-.2 6.782-2.618 6.979-6.98.059-1.28.073-1.689.073-4.948 0-3.259-.014-3.667-.072-4.947-.196-4.354-2.617-6.78-6.979-6.98-1.281-.059-1.69-.073-4.949-.073zm0 5.838c-3.403 0-6.162 2.759-6.162 6.162s2.759 6.163 6.162 6.163 6.162-2.759 6.162-6.163c0-3.403-2.759-6.162-6.162-6.162zm0 10.162c-2.209 0-4-1.79-4-4 0-2.209 1.791-4 4-4s4 1.791 4 4c0 2.21-1.791 4-4 4zm6.406-11.845c-.796 0-1.441.645-1.441 1.44s.645 1.44 1.441 1.44c.795 0 1.439-.645 1.439-1.44s-.644-1.44-1.439-1.44z"/></svg>
            </a>
            <a
              href="https://linkedin.com"
              target="_blank"
              rel="noreferrer"
              className="nl-social-link"
              aria-label="LinkedIn"
              onMouseMove={handleSocialMouseMove}
              onMouseLeave={handleSocialMouseLeave}
            >
              <svg viewBox="0 0 24 24"><path d="M4.98 3.5c0 1.381-1.11 2.5-2.48 2.5s-2.48-1.119-2.48-2.5c0-1.38 1.11-2.5 2.48-2.5s2.48 1.12 2.48 2.5zm.02 5.5h-5v14h5v-14zm7.982 0h-4.968v14h4.969v-7.391c0-2.094.197-3.689 1.769-3.689 1.552 0 1.579 1.83 1.579 3.827v7.253h4.965v-8.083c0-4.321-.892-7.417-5.805-7.417-2.395 0-4.004 1.309-4.664 2.548v-2.048z"/></svg>
            </a>
            <a
              href="mailto:hello@dishastra.com"
              className="nl-social-link"
              aria-label="Email"
              onMouseMove={handleSocialMouseMove}
              onMouseLeave={handleSocialMouseLeave}
            >
              <svg viewBox="0 0 24 24"><path d="M0 3v18h24v-18h-24zm6.623 7.929l-4.623 5.712v-9.458l4.623 3.746zm-4.141-5.929h19.035l-9.517 7.713-9.518-7.713zm5.694 7.188l3.824 3.099 3.83-3.104 5.612 6.817h-18.866l5.6-6.812zm9.208-1.264l4.616-3.741v9.348l-4.616-5.607z"/></svg>
            </a>
          </div>
        </motion.div>
      </div>
    </footer>
  );
};

export const NewLandingFooter = React.memo(NewLandingFooterComponent);
